import math

def is_square(n):
    if n < 0:
        return False
    if n == 0:
        return True
    sqrt_n = int(math.isqrt(n))
    return sqrt_n * sqrt_n == n

def is_cool(n):
    """
    Determines if n is a cool integer using backtracking search.
    A number is cool if a permutation (x_1, ..., x_n) of (1, ..., n) exists 
    such that no prefix sum is a perfect square.
    """

    # Initial check: If the total sum is a square, it cannot be cool.
    total_sum = n * (n + 1) // 2
    if is_square(total_sum):
        return False

    # The numbers available are {1, 2, ..., n}
    available = set(range(1, n + 1))

    def backtrack(current_sum, available_numbers):
        if not available_numbers:
            # Successfully formed a permutation of length n
            return True

        for x in sorted(list(available_numbers)): # Sorting helps with deterministic testing, not strictly necessary for correctness
            next_sum = current_sum + x

            if not is_square(next_sum):
                # If the next sum is not a square, try this path
                new_available = available_numbers - {x}
                if backtrack(next_sum, new_available):
                    return True

        return False

    # Start the search: sum=0, all numbers available
    return backtrack(0, available)

# Range to test: n=21 through n=70
