N_end = 70

non_cool_integers = []

print("Starting search for n=21 to n=70...")

for n in range(N_start, N_end + 1):
    try:
        if not is_cool(n):
            non_cool_integers.append(n)
            print(f"Found non-cool integer: n = {n}")
